<style>.platform-settings{display:grid;gap:20px;max-width:1100px}.platform-settings>form{margin:0;padding:24px;border:1px solid var(--line);border-radius:14px;background:var(--bg);box-shadow:0 8px 24px #0002}.platform-settings>form h3{margin:0 0 8px;font-size:18px}.platform-settings>form>p{margin:0 0 18px}.platform-settings .platform-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 20px;align-items:start}.platform-settings .platform-fields>label{display:grid;gap:7px;align-content:start}.platform-settings .platform-fields>label.check{display:flex;align-items:center;min-height:42px}.platform-settings .platform-fields small{color:var(--muted);font-size:12px}.platform-settings .button{margin-top:18px}.platform-settings form:has(input[type="number"][max="365"]) label:last-child{display:none}</style>
<style>.settings-tabs{display:flex;gap:6px;padding:5px;border:1px solid var(--line);border-radius:10px;background:var(--rail);width:max-content;max-width:100%;margin:6px 0 2px}.settings-tabs button{border:0;background:transparent;color:var(--muted);padding:10px 16px;border-radius:7px;font:inherit;cursor:pointer}.settings-tabs button.active{background:var(--bg);color:var(--text);box-shadow:0 2px 8px #0003}.platform-settings.tab-email>form:nth-of-type(n+3),.platform-settings.tab-realtime>form:nth-of-type(-n+2),.platform-settings.tab-realtime>form:nth-of-type(4),.platform-settings.tab-backups>form:nth-of-type(-n+3){display:none}@media(max-width:600px){.settings-tabs{width:100%;overflow:auto}.settings-tabs button{flex:1;white-space:nowrap;padding-inline:10px}}</style>
<style>.platform-settings>.notice{position:fixed;top:76px;right:24px;z-index:10000;width:min(420px,calc(100vw - 32px));margin:0;padding:14px 18px;border:1px solid #35b779;border-radius:10px;background:#10251d;color:#e8fff3;box-shadow:0 12px 32px #0005}.platform-settings>.notice.admin-error{border-color:#ef6a6a;background:#32191c}@media(max-width:600px){.platform-settings>.notice{top:62px;right:16px;left:16px;width:auto}}</style>
<style>.platform-settings .judibas-toast{position:fixed;top:76px;right:24px;z-index:10000;width:min(420px,calc(100vw - 32px));padding:14px 18px;border:1px solid #35b779;border-radius:10px;background:#10251d;color:#e8fff3;box-shadow:0 12px 32px #0005}.platform-settings .judibas-toast.error{border-color:#ef6a6a;background:#32191c}.platform-settings .judibas-toast-dot{display:inline-block;width:8px;height:8px;margin-right:10px;border-radius:50%;background:#35d07f}.platform-settings .judibas-toast.error .judibas-toast-dot{background:#ff7777}</style>
<style>.platform-settings form>.button{display:inline-flex!important;align-items:center;width:auto!important;vertical-align:middle}.platform-settings form>.button+.button{margin-left:10px!important}.platform-settings form .button{display:inline-flex;align-items:center;width:auto}.platform-settings form .button+.button{margin-left:10px}.platform-settings .platform-fields>label.check{width:max-content;max-width:100%;white-space:nowrap}.platform-settings .platform-fields>label.check input{flex:0 0 auto}.platform-settings .platform-fields>label:has(input[type="checkbox"]){grid-column:auto}.platform-settings form.admin-editor{min-height:0}</style>
<script setup lang="ts">
import {ref,watch,onMounted} from 'vue';
const props=defineProps<{csrf?:string}>();
const settings=ref<any>(null),backups=ref<any>(null),busy=ref(false),error=ref(''),message=ref(''),testEmail=ref(''),activeTab=ref('email');
watch(message,(value)=>{if(value)window.setTimeout(()=>{if(message.value===value)message.value='';},4500);});watch(error,(value)=>{if(value)window.setTimeout(()=>{if(error.value===value)error.value='';},6000);});
async function request(path='',body?:any){const r=await fetch('/admin/api/platform-settings'+path,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message||'Unable to complete this action.');return d;}
async function load(){try{settings.value=await request();settings.value.mail.scheme||='smtp';const r=await fetch('/admin/api/platform-settings/backups',{headers:{Accept:'application/json'}});backups.value=await r.json();const detected=Intl.DateTimeFormat().resolvedOptions().timeZone;if(detected&&(!backups.value.timezone||backups.value.timezone==='Asia/Karachi'))backups.value.timezone=detected;}catch(e){error.value=(e as Error).message;}}
async function saveBackups(){busy.value=true;error.value='';message.value='';try{const r=await fetch('/admin/api/platform-settings/backups',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:JSON.stringify(backups.value)});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message);message.value=d.message;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function runBackup(){busy.value=true;try{const r=await fetch('/admin/api/platform-settings/backups/run',{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf||''}});const d=await r.json();if(!r.ok)throw Error(d.message);message.value=d.message;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function addBackupFrequencies(){const select=Array.from(document.querySelectorAll('.platform-settings select')).find((node:any)=>Array.from(node.options).some((item:any)=>item.value==='every_2_days')) as HTMLSelectElement|null;if(select)for(const option of [{value:'every_15_days',label:'Every 15 days'},{value:'monthly',label:'Monthly'}])if(!Array.from(select.options).some(item=>item.value===option.value)){const node=document.createElement('option');node.value=option.value;node.textContent=option.label;select.appendChild(node);}const retention=document.querySelector('.platform-settings input[max="365"]');retention?.parentElement?.remove();}
function detectTimezone(){if(backups.value){const zone=Intl.DateTimeFormat().resolvedOptions().timeZone;if(zone){backups.value.timezone=zone;message.value=`Timezone detected: ${zone}`;}}}
async function submit(kind:string,test=false){busy.value=true;error.value='';message.value='';try{const d=await request('/'+kind+(test?'/test':''),test?(kind==='mail'?{test_email:testEmail.value}:{}):settings.value[kind]);message.value=d.message;if(!test)await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(async()=>{await load();addBackupFrequencies();});
</script>
<template>
<div class="platform-settings" :class="'tab-'+activeTab"><h2>Shared product settings</h2><p class="muted">Super admin manages one email and realtime configuration for PMS, Communication, and future products.</p><nav class="settings-tabs" aria-label="Settings sections"><button type="button" :class="{active:activeTab==='email'}" @click="activeTab='email'">Email</button><button type="button" :class="{active:activeTab==='realtime'}" @click="activeTab='realtime'">Realtime</button><button type="button" :class="{active:activeTab==='backups'}" @click="activeTab='backups'">Database backups</button></nav>
<div v-if="error" class="judibas-toast error" role="alert"><span class="judibas-toast-dot"></span>{{error}}</div><div v-if="message" class="judibas-toast" role="status"><span class="judibas-toast-dot"></span>{{message}}</div>
<p v-if="!settings&&!error" role="status">Loading settings?</p>
<template v-if="settings">
<form class="admin-editor" @submit.prevent="submit('mail')"><h3>Email server</h3><div class="platform-fields">
<label v-for="field in ['host','username','from_name']" :key="field">{{({host:'SMTP host',username:'Username',from_name:'Sender name'} as Record<string,string>)[field]}}<input v-model="settings.mail[field]" maxlength="255"></label>
<label>Sender email<input type="email" v-model="settings.mail.from_address"></label><label>Port<input type="number" v-model.number="settings.mail.port" min="1" max="65535" required></label>
<label>Encryption<select v-model="settings.mail.scheme"><option value="smtp">STARTTLS (usually 587)</option><option value="smtps">SSL (usually 465)</option></select></label>
<label>SMTP password<input type="password" v-model="settings.mail.password" autocomplete="new-password" placeholder="Leave blank to keep saved password"><small>{{settings.mail.password_saved?'Password saved securely.':'No saved password.'}}</small></label>
<label class="check"><input type="checkbox" v-model="settings.mail.notification_emails_enabled">PMS notification emails</label><label class="check"><input type="checkbox" v-model="settings.mail.invitation_emails_enabled">Invitation emails across products</label>
<label>PMS daily sending limit<input type="number" v-model.number="settings.mail.daily_limit" min="0" max="100000"><small>0 means unlimited. This quota tracks PMS deliveries.</small></label><label>PMS warning threshold<input type="number" v-model.number="settings.mail.warning_threshold" min="0" :max="settings.mail.daily_limit"></label>
</div><button class="button primary" :disabled="busy">Save email settings</button></form>
<form class="admin-editor" @submit.prevent="submit('mail',true)"><h3>Test saved email connection</h3><label>Recipient<input type="email" v-model="testEmail" required></label><button class="button" :disabled="busy">Send test email</button></form>
<form class="admin-editor" @submit.prevent="submit('realtime')"><h3>Realtime updates</h3><label class="check"><input type="checkbox" v-model="settings.realtime.enabled">Enable live updates across products</label>
<label>Provider<select v-model="settings.realtime.provider"><option value="reverb">Laravel Reverb</option><option value="pusher">Pusher Channels</option></select></label>
<p v-if="settings.realtime.provider==='reverb'" class="muted">Uses the shared Reverb server credentials and connection in .env. Keep the Reverb server running. Switching from Pusher clears the saved Pusher credentials.</p>
<div v-else class="platform-fields"><label>App ID<input v-model="settings.realtime.app_id" required></label><label>App key<input v-model="settings.realtime.app_key" required></label><label>Cluster<input v-model="settings.realtime.cluster" required pattern="[A-Za-z0-9-]+"></label><label>App secret<input type="password" v-model="settings.realtime.app_secret" autocomplete="new-password" placeholder="Leave blank to keep saved secret"><small>{{settings.realtime.secret_saved?'Secret saved securely.':'No saved secret.'}}</small></label></div>
<p class="muted">Refresh open product tabs after changing the connection.</p><button class="button primary" :disabled="busy">Save realtime settings</button><button class="button" type="button" :disabled="busy||!settings.realtime.enabled" @click="submit('realtime',true)">Test saved connection</button></form>
<form v-if="backups" class="admin-editor" @submit.prevent="saveBackups"><h3>Database backups</h3><p class="muted">Schedule PostgreSQL ZIP backups and email them to selected recipients.</p><div class="platform-fields"><label class="check"><input type="checkbox" v-model="backups.enabled">Enable scheduled backups</label><label>Frequency<select v-model="backups.frequency"><option value="daily">Daily</option><option value="every_2_days">Every 2 days</option><option value="weekly">Weekly</option></select></label><label>Time<input type="time" v-model="backups.time" required></label><label>Timezone<input v-model="backups.timezone" required></label><label>Recipient email(s)<input v-model="backups.recipients" required placeholder="admin@example.com"><small>Separate addresses with commas.</small></label><label>Keep backups<input type="number" v-model.number="backups.retention" min="1" max="365" required></label></div><button class="button primary" :disabled="busy">Save backup settings</button><button class="button" type="button" :disabled="busy" @click="runBackup">Run backup now</button><small v-if="backups.last_run_at" class="muted">Last run: {{new Date(backups.last_run_at).toLocaleString()}} · {{backups.last_status}}</small></form>
<p class="muted">Cloudflare R2 stores attachments; Cloudflare TURN relays voice calls. Those credentials remain in .env and are separate from Reverb/Pusher live updates.</p>
</template></div>
</template>
<style scoped>.platform-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.platform-settings select{width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:inherit}.platform-settings .button+.button{margin-left:10px}@media(max-width:700px){.platform-fields{grid-template-columns:1fr}}</style>
